function historyStatusClass(status){if(status==='delivered')return'bg-emerald-100 text-emerald-700 dark:bg-emerald-950/60 dark:text-emerald-300';if(status==='completed')return'bg-sky-100 text-sky-700 dark:bg-sky-950/60 dark:text-sky-300';return'bg-amber-100 text-amber-700 dark:bg-amber-950/60 dark:text-amber-300'}
