function groupHistoryEntries(entries){const groups=[];const seen=new Map();entries.forEach(entry=>{const key=entry.orderId||entry.id||`${entry.createdAt}-${entry.title}`;let group=seen.get(key);if(!group){group={orderId:entry.orderId||key,createdAt:entry.createdAt,orderStatus:entry.orderStatus||'pending',customerName:entry.customerName||'',customerEmail:entry.customerEmail||'',items:[]};seen.set(key,group);groups.push(group)}group.items.push(entry);if(!group.createdAt)group.createdAt=entry.createdAt;if(!group.orderStatus&&entry.orderStatus)group.orderStatus=entry.orderStatus;if(!group.customerName&&entry.customerName)group.customerName=entry.customerName;if(!group.customerEmail&&entry.customerEmail)group.customerEmail=entry.customerEmail});return groups}
function recordBasketHistory(order){if(!order||!Array.isArray(order.items)||!order.items.length)return;const history=basketHistory();const keys=new Set(order.items.map(item=>historyEntryKey(order.id,item.id)));const remaining=history.filter(entry=>!keys.has(historyEntryKey(entry.orderId,entry.itemId)));const ownerEmail=String(order.customerEmail||historyOwnerEmail()).trim().toLowerCase();order.items.slice().reverse().forEach(item=>{remaining.unshift({id:`hist-${order.id}-${item.id}`,orderId:order.id,itemId:item.id,productId:item.productId,title:item.title,price:Number(item.price||0),image:resolveHistoryImage(item.productId,item.image),qty:Number(item.qty||1),source:'Order',customerEmail:ownerEmail,customerName:order.customerName||'',orderStatus:order.status||'pending',available:item.available!==false,createdAt:order.createdAt||new Date().toLocaleString()})});saveBasketHistory(remaining.slice(0,100));renderBasketHistory()}
function syncBasketHistory(){const history=basketHistory();if(!history.length)return history;const ordersById=new Map(txs().map(order=>{const copy={...order,items:(order.items||[]).map(item=>({...item}))};return [copy.id,recalc(copy)]}));let changed=false;const next=history.map(entry=>{if(!entry.orderId||!entry.itemId)return entry;const order=ordersById.get(entry.orderId);if(!order)return entry;const item=(order.items||[]).find(value=>value.id===entry.itemId);if(!item)return entry;const synced={...entry,title:item.title||entry.title,price:Number(item.price??entry.price??0),qty:Number(item.qty??entry.qty??1),productId:item.productId||entry.productId,image:resolveHistoryImage(item.productId,entry.image),available:item.available!==false,orderStatus:order.status||entry.orderStatus,customerEmail:order.customerEmail||entry.customerEmail,customerName:order.customerName||entry.customerName,createdAt:order.createdAt||entry.createdAt};if(synced.title!==entry.title||synced.price!==entry.price||synced.qty!==entry.qty||synced.productId!==entry.productId||synced.image!==entry.image||synced.available!==entry.available||synced.orderStatus!==entry.orderStatus||synced.customerEmail!==entry.customerEmail||synced.customerName!==entry.customerName||synced.createdAt!==entry.createdAt)changed=true;return synced});if(changed)saveBasketHistory(next);return next}
