function openCheckoutModal(){if(!S.cart.length){toast('Add at least one item before checkout.','shopping-cart','bg-slate-900 text-white');return}if(!location.pathname.toLowerCase().endsWith('checkout.html')){location.href='./checkout.html';return}const modal=$('checkout-modal');if(modal){S.step=1;syncStep();prefill();clearInlineStatus('checkout-form-status');clearFormErrors('cust-name','cust-phone','cust-address','card-holder','card-num','card-expiry','card-cvv');modal.classList.remove('opacity-0','pointer-events-none')}}
