function syncStep(){for(let i=1;i<=3;i++){$(`checkout-form-step-${i}`)?.classList.toggle('hidden',i!==S.step);const b=$(`step-${i}-badge`),l=$(`step-${i}-label`),active=i<=S.step;if(b){b.classList.toggle('bg-brand-600',active);b.classList.toggle('text-white',active);b.classList.toggle('bg-slate-200',!active);b.classList.toggle('dark:bg-slate-800',!active);b.classList.toggle('text-slate-600',!active);b.classList.toggle('dark:text-slate-400',!active)}if(l){l.classList.toggle('text-brand-600',active);l.classList.toggle('font-semibold',active);l.classList.toggle('text-slate-600',!active);l.classList.toggle('dark:text-slate-400',!active)}}$('checkout-line-progress')&&($('checkout-line-progress').style.width=S.step===1?'0%':S.step===2?'50%':'100%');$('checkout-back-btn')?.classList.toggle('hidden',S.step===1);$('checkout-next-btn')?.classList.toggle('hidden',S.step===3)}
