function handleCheckoutNext(){clearInlineStatus('checkout-form-status');if(S.step===1){const n=$('cust-name')?.value.trim(),p=$('cust-phone')?.value.trim(),a=$('cust-address')?.value.trim();if(!n)return invalidateField('cust-name','Please tell us the name on the order.','checkout-form-status');if(!p)return invalidateField('cust-phone','Please add a phone number so the rider can reach you.','checkout-form-status');if(!/^[0-9+()\-\s]{7,20}$/.test(p))return invalidateField('cust-phone','Use a valid phone number with at least 7 digits.','checkout-form-status');if(!a)return invalidateField('cust-address','Please enter a delivery address before continuing.','checkout-form-status');window._contact={name:n,phone:p,address:a,notes:$('cust-notes')?.value.trim()||''};S.step=2;syncStep();return}const m=document.querySelector('input[name="payment-method"]:checked')?.value||'cash';if(m==='card'){const holder=$('card-holder')?.value.trim(),num=$('card-num')?.value.replace(/\s/g,''),cvv=$('card-cvv')?.value.trim();const expiryInput=$('card-expiry');const expiryStatus=getExpiryStatus(expiryInput?.value.trim());if(!holder)return invalidateField('card-holder','Enter the name printed on your card.','checkout-form-status');if(num.length!==16)return invalidateField('card-num','Enter a 16-digit card number.','checkout-form-status');if(!/^\d{3}$/.test(cvv))return invalidateField('card-cvv','Enter the 3-digit CVV on the back of the card.','checkout-form-status');if(!expiryStatus.ok){if(expiryInput){expiryInput.setCustomValidity(expiryStatus.message);expiryInput.reportValidity();clearFieldErrorVisual(expiryInput)}return invalidateField('card-expiry','Use a valid card expiry date in MM/YY format.','checkout-form-status')} }completeCheckout(m)}
