function txs(){return J(SK.x,[])} function saveTx(v){W(SK.x,v)}
function recalc(o){const sub=o.items.filter(i=>i.available!==false).reduce((a,b)=>a+b.price*b.qty,0),disc=o.subtotal>0?Number((o.discountAmount*(sub/o.subtotal)).toFixed(2)):0;o.adjustedTotal=Number(Math.max(0,sub-disc+o.deliveryFee).toFixed(2));return o}
function updateTransactionItemAvailability(orderId,itemId,available){const x=txs(),o=x.find(v=>v.id===orderId);if(!o)return;if(o.status==='delivered'){toast('Delivered orders are locked. Change the status back to Pending to edit item availability.','lock','bg-amber-600 text-white');renderTransactions();return}const i=o.items.find(v=>v.id===itemId);if(!i)return;i.available=available;recalc(o);saveTx(x);renderTransactions();renderAdminMetrics()}
