function renderAdminMetrics(){const x=txs(),t=x.length,p=x.filter(v=>v.status==='pending').length,c=x.filter(v=>v.status==='completed').length,d=x.filter(v=>v.status==='delivered').length;$('metric-total-orders')&&($('metric-total-orders').textContent=String(t));$('metric-pending-orders')&&($('metric-pending-orders').textContent=String(p));$('metric-completed-orders')&&($('metric-completed-orders').textContent=String(c));$('metric-delivered-orders')&&($('metric-delivered-orders').textContent=String(d));$('admin-status-list')&&($('admin-status-list').innerHTML=`<div class="rounded-3xl bg-amber-50 p-5"><p class="text-[11px] uppercase tracking-wider text-amber-600 font-bold">Pending Requests</p><p class="mt-3 text-4xl font-black text-amber-700">${p}</p></div><div class="rounded-3xl bg-sky-50 p-5"><p class="text-[11px] uppercase tracking-wider text-sky-600 font-bold">Completed Requests</p><p class="mt-3 text-4xl font-black text-sky-700">${c}</p></div><div class="rounded-3xl bg-emerald-50 p-5"><p class="text-[11px] uppercase tracking-wider text-emerald-600 font-bold">Delivered Requests</p><p class="mt-3 text-4xl font-black text-emerald-700">${d}</p></div>`) }
