function fileToDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('Unable to read image file.'));reader.readAsDataURL(file)})}
function setProductManagerStatus(message,tone='success'){const box=$('product-manager-status');if(!box)return;const tones={success:'border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-900/50 dark:bg-emerald-950/40 dark:text-emerald-300',info:'border-sky-200 bg-sky-50 text-sky-700 dark:border-sky-900/50 dark:bg-sky-950/40 dark:text-sky-300',error:'border-red-200 bg-red-50 text-red-700 dark:border-red-900/50 dark:bg-red-950/40 dark:text-red-300'};box.className=`mb-4 rounded-2xl border px-4 py-3 text-sm font-semibold ${tones[tone]||tones.success}`;box.textContent=message;box.classList.remove('hidden')}
